import pandas as pd
from Bio.Blast import NCBIWWW, NCBIXML

def run_blast_search(protein_id, database='nr', e_value=1e-10):
    """Run BLAST search for protein homologs."""
    from Bio import SeqIO
    result_handle = NCBIWWW.qblast('blastp', database, protein_id)
    blast_records = NCBIXML.parse(result_handle)

    homologs = []
    for record in blast_records:
        for alignment in record.alignments:
            for hsp in alignment.hsps:
                if hsp.expect < e_value:
                    homologs.append({
                        'accession': alignment.accession,
                        'title': alignment.title[:80],
                        'e_value': hsp.expect,
                        'identity': hsp.identities / hsp.align_length * 100,
                        'coverage': hsp.align_length
                    })

    df = pd.DataFrame(homologs)
    df.to_csv('homolog_summary.csv', index=False)
    return df
